CHUNK = '        if self.config.get("acceptance_authority") != "external_verifier":\n            raise StandardConfigurationError(\n                "acceptance_authority must be \'external_verifier\'"\n            )\n\n        # Merely accessing the property validates it.\n        _ = self.governing_context_id\n\n    def resolve_profile(self, requested_profile: str | None) -> Profile:\n        # Missing profile -> locked kernel fallback.\n        if requested_profile is None:\n            return self.profiles["general"]\n\n        # A supplied but invalid value is a configuration error, not a silent fallback.\n        try:\n            return self.profiles[requested_profile]\n        except KeyError as exc:\n            raise UnknownProfileError(\n                f"Unknown task profile {requested_profile!r}. "\n                "Supply a valid profile or omit it to use general."\n            ) from exc\n\n    def resolve_overlay(self, language: str | None) -> Profile | None:\n        if language is None:\n            return None\n        overlays = self.config.get("language_overlays", {})\n        profile_id = overlays.get(language)\n        if profile_id is None:\n            raise UnknownLanguageOverlayError(\n                f"No deterministic language overlay configured for {language!r}"\n            )\n        return self.profiles[profile_id]\n\n    def _rule_applies(self, rule: Rule, profile: str, language: str | None) -> bool:\n        # v1 intentionally ignores applies_to.paths.\n        if rule.applies_to.profiles:\n            if profile not in rule.applies_to.profiles and "general" not in rule.applies_to.profiles:\n                return False\n        if rule.applies_to.languages:\n            if language is None or language not in rule.applies_to.languages:\n                return False\n        return True\n\n    def _effective_rule(self, base_rule: Rule, profile: str, language: str | None) -> Rule:\n        local = self.specializations.get(base_rule.id)\n        if local and self._rule_applies(local, profile, language):\n            return local\n        return base_rule\n\n    def compile_context(\n        self,\n        *,\n        profile: str | None,\n        language: str | None = None,\n    ) -> ContextBundle:\n        task_profile = self.resolve_profile(profile)\n        overlay = self.resolve_overlay(language)\n\n        ids: list[str] = list(task_profile.preload)\n\n        extensions = self.config.get("profile_extensions", {})\n        ids.extend(extensions.get(task_profile.id, []))\n\n        if overlay is not None:\n            ids.extend(overlay.preload)\n\n        seen: set[str] = set()\n        selected: list[Rule] = []\n        for rid in ids:\n            if rid in seen:\n                continue\n            seen.add(rid)\n            base = self.rules[rid]\n'
